import{_ as l,a0 as d,w as u,s,ao as x,I as n,a1 as i,A as e,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"無需 root 實現在 Android 設備上運行 Linux | LCTT x X-CMD","titleTemplate":false,"description":"無需 root 實現在 Android 設備上運行 Linux | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"無需 root 實現在 Android 設備上運行 Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"無需 root 實現在 Android 設備上運行 Linux | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171024 Run Linux On Android Devices, No Rooting Required","title":"無需 root 實現在 Android 設備上運行 Linux","tag":"201801","desc":""},"relativePath":"201801/20171024 Run Linux On Android Devices, No Rooting Required.md","filePath":"[post].md"}'),p={name:"201801/20171024 Run Linux On Android Devices, No Rooting Required.md"};function m(a,o,T,g,A,w){const r=d("Link");return u(),s("div",null,[o[16]||(o[16]=x('<h1 id="無需-root-實現在-android-設備上運行-linux" tabindex="-1">無需 root 實現在 Android 設備上運行 Linux <a class="header-anchor" href="#無需-root-實現在-android-設備上運行-linux" aria-label="Permalink to “無需 root 實現在 Android 設備上運行 Linux”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/10/Termux-720x340.jpg" alt=""></p><p>曾經，我嘗試過搜索一種簡單的可以在 Android 上運行 Linux 的方法。我當時唯一的意圖只是想使用 Linux 以及一些基本的應用程序，比如 SSH，Git，awk 等。要求的並不多！我不想 root 我的 Android 設備。我有一台平板電腦，主要用於閲讀電子書、新聞和少數 Linux Blog。除此之外也不怎麼用它了。因此我決定用它來實現一些 Linux 的功能。在 Google Play 商店上瀏覽了幾分鐘後，一個應用程序瞬間引起了我的注意，勾起了我實驗的慾望。如果你也想在 Android 設備上運行 Linux，這個應用可能會有所幫助。</p><h3 id="termux-在-android-和-chrome-os-上運行的-android-終端模擬器" tabindex="-1">Termux - 在 Android 和 Chrome OS 上運行的 Android 終端模擬器 <a class="header-anchor" href="#termux-在-android-和-chrome-os-上運行的-android-終端模擬器" aria-label="Permalink to “Termux - 在 Android 和 Chrome OS 上運行的 Android 終端模擬器”">​</a></h3><p><strong>Termux</strong> 是一個 Android 終端模擬器以及提供 Linux 環境的應用程序。跟許多其他應用程序不同，你無需 root 設備也無需進行設置。它是開箱即用的！它會自動安裝好一個最基本的 Linux 系統，當然你也可以使用 APT 軟件包管理器來安裝其他軟件包。總之，你可以讓你的 Android 設備變成一台袖珍的 Linux 電腦。它不僅適用於 Android，你還能在 Chrome OS 上安裝它。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/termux.png" alt=""></p><p>Termux 提供了許多重要的功能，比您想像的要多。</p><ul><li>它允許你通過 openSSH 登錄遠程服務器。</li><li>你還能夠從遠程系統 SSH 到 Android 設備中。</li><li>使用 rsync 和 curl 將您的智能手機通訊錄同步到遠程系統。</li><li>支持不同的 shell，比如 BASH、ZSH，以及 FISH 等等。</li><li>可以選擇不同的文本編輯器來編輯/查看文件，支持 Emacs、Nano 和 Vim。</li><li>使用 APT 軟件包管理器在 Android 設備上安裝你想要的軟件包。支持 Git、Perl、Python、Ruby 和 Node.js 的最新版本。</li><li>可以將 Android 設備與藍牙鍵盤、鼠標和外置顯示器連接起來，就像是整合在一起的設備一樣。Termux 支持鍵盤快捷鍵。</li><li>Termux 支持幾乎所有 GNU/Linux 命令。</li></ul><p>此外通過安裝插件可以啓用其他一些功能。例如，<strong>Termux：API</strong> 插件允許你訪問 Android 和 Chrome 的硬件功能。其他有用的插件包括：</p><ul><li>Termux：Boot - 設備啓動時運行腳本</li><li>Termux：Float - 在浮動窗口中運行 Termux</li><li>Termux：Styling - 提供配色方案和支持 Powerline 的字體來定製 Termux 終端的外觀。</li><li>Termux：Task - 提供一種從任務欄類的應用中調用 Termux 可執行文件的簡易方法。</li><li>Termux：Widget - 提供一種從主屏幕啓動小腳本的建議方法。</li></ul><p>要了解更多有關 termux 的信息，請長按終端上的任意位置並選擇“幫助”菜單選項來打開內置的幫助部分。它唯一的缺點就是<strong>需要 Android 5.0 及更高版本</strong>。如果它支持 Android 4.x 和舊版本的話，將會更有用的多。你可以在 <strong>Google Play 商店</strong>和 <strong>F-Droid</strong> 中找到並安裝 Termux。</p><p>要在 Google Play 商店中安裝 Termux，點擊下面按鈕。</p>',12)),n("p",null,[i(r,{href:"https://play.google.com/store/apps/details?id=com.termux"},{default:e(()=>[...o[0]||(o[0]=[n("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/05/google-play-icon.png",alt:""},null,-1)])]),_:1})]),o[17]||(o[17]=n("p",null,"若要在 F-Droid 中安裝，則點擊下面按鈕。",-1)),n("p",null,[i(r,{href:"https://f-droid.org/packages/com.termux/"},{default:e(()=>[...o[1]||(o[1]=[n("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/10/F-droid-1.png",alt:""},null,-1)])]),_:1})]),o[18]||(o[18]=n("p",null,"你現在知道如何使用 Termux 在 Android 設備上使用 Linux 了。你有用過其他更好的應用嗎？請在下面留言框中留言。我很樂意也去嘗試他們！",-1)),o[19]||(o[19]=n("p",null,"此致敬禮！",-1)),o[20]||(o[20]=n("p",null,"相關資源：",-1)),n("ul",null,[n("li",null,[i(r,{href:"https://termux.com/"},{default:e(()=>[...o[2]||(o[2]=[t("Termux 官網 ",-1)])]),_:1})])]),o[21]||(o[21]=n("hr",null,null,-1)),n("p",null,[o[4]||(o[4]=t("via: ",-1)),i(r,{href:"https://www.ostechnix.com/termux-run-linux-android-devices-no-rooting-required/"},{default:e(()=>[...o[3]||(o[3]=[t("https://www.ostechnix.com/termux-run-linux-android-devices-no-rooting-required/",-1)])]),_:1})]),n("p",null,[o[8]||(o[8]=t("作者：",-1)),i(r,{href:"https://www.ostechnix.com/author/sk/"},{default:e(()=>[...o[5]||(o[5]=[t("SK",-1)])]),_:1}),o[9]||(o[9]=t(" 譯者：",-1)),i(r,{href:"https://github.com/lujun9972"},{default:e(()=>[...o[6]||(o[6]=[t("lujun9972",-1)])]),_:1}),o[10]||(o[10]=t(" 校對：",-1)),i(r,{href:"https://github.com/wxy"},{default:e(()=>[...o[7]||(o[7]=[t("wxy",-1)])]),_:1})]),n("p",null,[o[13]||(o[13]=t("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...o[11]||(o[11]=[t("LCTT",-1)])]),_:1}),o[14]||(o[14]=t(" 原創編譯，",-1)),i(r,{href:"https://linux.cn/"},{default:e(()=>[...o[12]||(o[12]=[t("Linux中國",-1)])]),_:1}),o[15]||(o[15]=t(" 榮譽推出",-1))])])}const S=l(p,[["render",m]]);export{C as __pageData,S as default};
